import { Agent, getAgentByName, routeAgentRequest } from 'agents';

export class Chat extends Agent {
  async onMessage(connection, message) {
    connection.send(`echo: ${message}`);
  }
}

export class Report extends Agent {
  initialState = { topic: null, report: null };

  async generate(topic) {
    const report = `Report on "${topic}": (placeholder content)`;
    await this.setState({ topic, report });
    return report;
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === '/reports' && request.method === 'POST') {
      let body;
      try {
        body = await request.json();
      } catch {
        return Response.json({ error: 'Invalid JSON body' }, { status: 400 });
      }
      if (typeof body?.topic !== 'string' || !body.topic) {
        return Response.json({ error: '`topic` must be a non-empty string' }, { status: 400 });
      }

      // A fresh random name per request gives a new, separate Report instance.
      // The same name reaches it again via getAgentByName(env.Report, id)
      // or /agents/report/<id>.
      const id = crypto.randomUUID();
      const stub = await getAgentByName(env.Report, id);
      const report = await stub.generate(body.topic);
      return Response.json({ id, report });
    }

    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

